from dataclasses import dataclass

@dataclass
class Order:
    id: str
    user_id: str
    total: float
    status: str = "pending"


def place_order(order: Order, inventory_ok: bool, payment_ok: bool) -> Order:
    if not inventory_ok:
        order.status = "rejected_inventory"
        return order
    if not payment_ok:
        order.status = "rejected_payment"
        return order
    order.status = "confirmed"
    return order

const seen = new Set<string>()

export function ensureIdempotent(key: string, fn: () => void) {
  if (seen.has(key)) return
  seen.add(key)
  fn()
}
